CREATE TABLE IF NOT EXISTS p14_qualification_deliveries (id CHAR(64) PRIMARY KEY,destination_server_id BIGINT NOT NULL,season_index INT NOT NULL,payload LONGBLOB NOT NULL,payload_hash CHAR(64) NOT NULL,confirmed BOOLEAN NOT NULL DEFAULT FALSE,created_at BIGINT NOT NULL,confirmed_at BIGINT NOT NULL DEFAULT 0,attempt_count BIGINT NOT NULL DEFAULT 0,INDEX(destination_server_id),INDEX(season_index),INDEX(confirmed)) ENGINE=InnoDB;
